// Devuelve los apartados de UN cliente, filtrados por su telefono.
//
// El filtro es exacto (comparando solo los digitos del telefono): asi el bot
// nunca enseña los apartados de otra persona, aunque dos clientes se parezcan.
const consulta = $('Datos de la consulta').first().json ?? {};
const telefonoPedido = String(consulta.telefono ?? '').replace(/[^0-9]/g, '');

const digitos = (s) => String(s ?? '').replace(/[^0-9]/g, '');
const euros = (n) => Number(n ?? 0).toFixed(2).replace('.', ',') + ' EUR';

const candidatos = $input.all()
  .flatMap((i) => (Array.isArray(i.json) ? i.json : [i.json]))
  .filter((a) => a && a.id !== undefined);

const apartados = telefonoPedido
  ? candidatos.filter((a) => digitos(a.telefono) === telefonoPedido)
  : [];

const total = apartados.reduce((s, a) => s + Number(a.pendiente ?? 0), 0);

return [{
  json: {
    telefono: telefonoPedido,
    encontrado: apartados.length > 0,
    apartados: apartados.map((a) => ({
      id: a.id,
      producto: a.producto,
      talla: a.talla,
      precio: a.precio,
      abonado: a.abonado,
      pendiente: a.pendiente,
      fecha_limite: a.fecha_limite,
      estado: a.estado,
    })),
    total_pendiente: Number(total.toFixed(2)),
    total_pendiente_texto: euros(total),
  },
}];
